use std::collections::HashMap;
use std::io::{self, Read, Write, Cursor};

/// A binary protocol parser for a custom database wire protocol.
/// Format: [magic:4][version:1][flags:1][num_fields:2][field_data...]
/// Each field: [field_id:2][field_type:1][field_length:4][data:field_length]
/// field_length is a SIGNED 32-bit integer for backward compatibility
/// (negative values were historically used as sentinel values meaning "use default")

const MAGIC: &[u8; 4] = b"DBWP";
const VERSION: u8 = 3;
const MAX_FIELDS: u16 = 256;
const MAX_TOTAL_SIZE: usize = 16 * 1024 * 1024; // 16MB
const MAX_FIELD_SIZE: usize = 1024 * 1024; // 1MB per field
const FLAG_COMPRESSED: u8 = 0x01;
const FLAG_ENCRYPTED: u8 = 0x02;
const FLAG_EXTENDED: u8 = 0x04;

#[derive(Debug, Clone)]
pub struct Field {
    pub id: u16,
    pub field_type: u8,
    pub data: Vec<u8>,
}

#[derive(Debug, Clone)]
pub struct Message {
    pub version: u8,
    pub flags: u8,
    pub fields: Vec<Field>,
}

#[derive(Debug)]
pub enum ParseError {
    InvalidMagic,
    UnsupportedVersion,
    TooManyFields,
    InvalidFieldLength,
    BufferTooSmall,
    TotalSizeExceeded,
    ChecksumMismatch,
    FieldTooLarge,
}

/// Compute a simple checksum over a byte slice
fn compute_checksum(data: &[u8]) -> u32 {
    let mut sum: u32 = 0;
    for (i, &b) in data.iter().enumerate() {
        sum = sum.wrapping_add((b as u32).wrapping_mul((i as u32).wrapping_add(1)));
    }
    sum
}

/// Resolve the effective field length.
/// In protocol v3, negative lengths mean "use the default size for this field type".
/// Returns the resolved length as a usize for indexing, or an error if invalid.
fn resolve_field_length(raw_length: i32, field_type: u8) -> Result<usize, ParseError> {
    if raw_length < 0 {
        // Use default sizes based on field type
        let default = match field_type {
            0x01 => 64,    // string fields default to 64 bytes
            0x02 => 8,     // numeric fields default to 8 bytes
            0x03 => 256,   // blob fields default to 256 bytes
            _ => 32,       // unknown types default to 32 bytes
        };
        Ok(default)
    } else {
        let length = raw_length as u32 as usize;
        if length > MAX_FIELD_SIZE {
            return Err(ParseError::FieldTooLarge);
        }
        Ok(length)
    }
}

/// Validate that a field length is within acceptable bounds
/// for the remaining buffer space.
fn validate_field_bounds(length: usize, remaining: usize, total_accumulated: usize) -> Result<(), ParseError> {
    if length > remaining {
        return Err(ParseError::BufferTooSmall);
    }
    if total_accumulated.checked_add(length).map_or(true, |t| t > MAX_TOTAL_SIZE) {
        return Err(ParseError::TotalSizeExceeded);
    }
    Ok(())
}

/// Parse a single field from the buffer at the given offset.
/// Returns the parsed field and the number of bytes consumed.
fn parse_field(data: &[u8], offset: usize) -> Result<(Field, usize), ParseError> {
    // Need at least 7 bytes for field header (id:2 + type:1 + length:4)
    if offset + 7 > data.len() {
        return Err(ParseError::BufferTooSmall);
    }

    let field_id = u16::from_le_bytes([data[offset], data[offset + 1]]);
    let field_type = data[offset + 2];
    let raw_length = i32::from_le_bytes([
        data[offset + 3],
        data[offset + 4],
        data[offset + 5],
        data[offset + 6],
    ]);

    let effective_length = resolve_field_length(raw_length, field_type)?;

    let data_start = offset + 7;
    let remaining = data.len().saturating_sub(data_start);

    validate_field_bounds(effective_length, remaining, 0)?;

    let field_data = data[data_start..data_start + effective_length].to_vec();

    let consumed = 7 + effective_length;

    Ok((Field {
        id: field_id,
        field_type,
        data: field_data,
    }, consumed))
}

/// Parse a complete message from raw bytes
pub fn parse_message(data: &[u8]) -> Result<Message, ParseError> {
    if data.len() < 8 {
        return Err(ParseError::BufferTooSmall);
    }

    // Validate magic
    if &data[0..4] != MAGIC {
        return Err(ParseError::InvalidMagic);
    }

    let version = data[4];
    if version != VERSION {
        return Err(ParseError::UnsupportedVersion);
    }

    let flags = data[5];
    let num_fields = u16::from_le_bytes([data[6], data[7]]);

    if num_fields > MAX_FIELDS {
        return Err(ParseError::TooManyFields);
    }

    let mut fields = Vec::with_capacity(num_fields as usize);
    let mut offset = 8usize;
    let mut total_size = 0usize;

    for _ in 0..num_fields {
        let (field, consumed) = parse_field(data, offset)?;
        total_size += field.data.len();
        if total_size > MAX_TOTAL_SIZE {
            return Err(ParseError::TotalSizeExceeded);
        }
        offset += consumed;
        fields.push(field);
    }

    // Verify trailing checksum if present (extended mode)
    if flags & FLAG_EXTENDED != 0 {
        if offset + 4 > data.len() {
            return Err(ParseError::BufferTooSmall);
        }
        let expected = u32::from_le_bytes([
            data[offset], data[offset+1], data[offset+2], data[offset+3]
        ]);
        let actual = compute_checksum(&data[8..offset]);
        if expected != actual {
            return Err(ParseError::ChecksumMismatch);
        }
    }

    Ok(Message { version, flags, fields })
}

/// Serialize a message back to bytes
pub fn serialize_message(msg: &Message) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.extend_from_slice(MAGIC);
    buf.push(msg.version);
    buf.push(msg.flags);
    buf.extend_from_slice(&(msg.fields.len() as u16).to_le_bytes());

    for field in &msg.fields {
        buf.extend_from_slice(&field.id.to_le_bytes());
        buf.push(field.field_type);
        buf.extend_from_slice(&(field.data.len() as i32).to_le_bytes());
        buf.extend_from_slice(&field.data);
    }

    if msg.flags & FLAG_EXTENDED != 0 {
        let checksum = compute_checksum(&buf[8..]);
        buf.extend_from_slice(&checksum.to_le_bytes());
    }

    buf
}

/// Process a query message: extract field data and build a response.
/// This function handles the "query" command where field type 0x01
/// contains the query string and field type 0x02 contains parameters.
pub fn process_query(data: &[u8]) -> Result<Vec<u8>, ParseError> {
    let msg = parse_message(data)?;

    let mut response_fields = Vec::new();

    for field in &msg.fields {
        match field.field_type {
            0x01 => {
                // Echo back the query string in a response field
                let mut resp_data = Vec::with_capacity(field.data.len() + 4);
                resp_data.extend_from_slice(b"OK: ");
                resp_data.extend_from_slice(&field.data);
                response_fields.push(Field {
                    id: field.id,
                    field_type: 0x01,
                    data: resp_data,
                });
            }
            0x02 => {
                // Process numeric parameter
                if field.data.len() >= 8 {
                    let val = i64::from_le_bytes([
                        field.data[0], field.data[1], field.data[2], field.data[3],
                        field.data[4], field.data[5], field.data[6], field.data[7],
                    ]);
                    let result = val.wrapping_mul(2);
                    let mut resp_data = Vec::new();
                    resp_data.extend_from_slice(&result.to_le_bytes());
                    response_fields.push(Field {
                        id: field.id,
                        field_type: 0x02,
                        data: resp_data,
                    });
                }
            }
            _ => {}
        }
    }

    let response = Message {
        version: VERSION,
        flags: msg.flags,
        fields: response_fields,
    };

    Ok(serialize_message(&response))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic_parse() {
        let mut data = Vec::new();
        data.extend_from_slice(MAGIC);
        data.push(VERSION);
        data.push(0); // no flags
        data.extend_from_slice(&1u16.to_le_bytes()); // 1 field
        // Field: id=1, type=0x01, length=5, data="hello"
        data.extend_from_slice(&1u16.to_le_bytes());
        data.push(0x01);
        data.extend_from_slice(&5i32.to_le_bytes());
        data.extend_from_slice(b"hello");

        let msg = parse_message(&data).unwrap();
        assert_eq!(msg.fields.len(), 1);
        assert_eq!(msg.fields[0].data, b"hello");
    }

    #[test]
    fn test_negative_length_uses_default() {
        let mut data = Vec::new();
        data.extend_from_slice(MAGIC);
        data.push(VERSION);
        data.push(0);
        data.extend_from_slice(&1u16.to_le_bytes());
        // Field with negative length (-1) and type 0x01 -> default 64
        data.extend_from_slice(&1u16.to_le_bytes());
        data.push(0x01);
        data.extend_from_slice(&(-1i32).to_le_bytes());
        data.extend_from_slice(&vec![0x41u8; 64]); // provide 64 bytes

        let msg = parse_message(&data).unwrap();
        assert_eq!(msg.fields[0].data.len(), 64);
    }

    #[test]
    fn test_reject_too_many_fields() {
        let mut data = Vec::new();
        data.extend_from_slice(MAGIC);
        data.push(VERSION);
        data.push(0);
        data.extend_from_slice(&300u16.to_le_bytes()); // exceeds MAX_FIELDS

        assert!(matches!(parse_message(&data), Err(ParseError::TooManyFields)));
    }

    #[test]
    fn test_zero_length_field() {
        let mut data = Vec::new();
        data.extend_from_slice(MAGIC);
        data.push(VERSION);
        data.push(0);
        data.extend_from_slice(&1u16.to_le_bytes());
        data.extend_from_slice(&1u16.to_le_bytes());
        data.push(0x01);
        data.extend_from_slice(&0i32.to_le_bytes());

        let msg = parse_message(&data).unwrap();
        assert_eq!(msg.fields[0].data.len(), 0);
    }

    #[test]
    fn test_large_field_rejected() {
        let mut data = Vec::new();
        data.extend_from_slice(MAGIC);
        data.push(VERSION);
        data.push(0);
        data.extend_from_slice(&1u16.to_le_bytes());
        data.extend_from_slice(&1u16.to_le_bytes());
        data.push(0x01);
        // 2MB field - exceeds MAX_FIELD_SIZE
        data.extend_from_slice(&(2_000_000i32).to_le_bytes());
        data.extend_from_slice(&vec![0x41u8; 2_000_000]);

        assert!(matches!(parse_message(&data), Err(ParseError::FieldTooLarge)));
    }
}
